ALTER TABLE `enterprise_info`
ADD COLUMN `address` VARCHAR(500) DEFAULT NULL COMMENT '企业地址',
ADD COLUMN `industry` VARCHAR(200) DEFAULT NULL COMMENT '所属产业',
ADD COLUMN `employee_count` INT DEFAULT 0 COMMENT '员工人数（人）',
ADD COLUMN `annual_output` DECIMAL(15,2) DEFAULT 0.00 COMMENT '年产值（万元）',
ADD COLUMN `annual_tax` DECIMAL(15,2) DEFAULT 0.00 COMMENT '年纳税额（万元）';

